<style>
.entity-hero{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0}.entity-tree{display:grid;gap:10px}.entity-node{border:1px solid var(--border);border-radius:14px;padding:14px;background:var(--surface)}.entity-node.root{border-width:2px}.entity-node small{display:block;color:var(--muted);margin-top:4px}.entity-indent{margin-left:28px}.template-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.template-card{display:flex;flex-direction:column;gap:10px}.template-card.active{outline:2px solid var(--accent)}.relation-line{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px}.readiness-score{font-size:2rem;font-weight:800}.entity-split{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(300px,.6fr);gap:18px}@media(max-width:960px){.entity-hero,.template-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.entity-split{grid-template-columns:1fr}}@media(max-width:620px){.entity-hero,.template-grid{grid-template-columns:1fr}.relation-line{grid-template-columns:1fr}.entity-indent{margin-left:12px}}
</style>
